const rows = $input.all().map(i => i.json);
const s = {};
for (const r of rows) { if (r.key) s[String(r.key).trim()] = (r.value === undefined || r.value === null) ? '' : String(r.value).trim(); }
const num = (v, d) => { const n = Number(v); return (String(v).trim() !== '' && Number.isFinite(n)) ? n : d; };
return [{ json: {
  what_we_sell: s.what_we_sell || '',
  who_buys: s.who_buys || '',
  signal_titles: (s.signal_titles || '').split(',').map(x => x.trim()).filter(Boolean),
  source_mode: (s.source_mode || 'sample').toLowerCase(),
  location: s.location || '',
  skip_recruiters: (s.skip_recruiters || 'yes').toLowerCase() === 'yes',
  max_post_age_days: num(s.max_post_age_days, 45),
  min_score: num(s.min_score, 4),
  daily_cap: num(s.daily_cap, 5),
  approval_mode: (s.approval_mode || 'on').toLowerCase(),
  sender_name: s.sender_name || '',
  sender_company: s.sender_company || '',
  postal_address: s.postal_address || '',
  tone: s.tone || ''
} }];

const daysFrom = (t) => {
  if (t === undefined || t === null || t === '') return 0;
  const s = String(t).toLowerCase();
  const n = parseInt(s.replace(/[^0-9]/g, ''), 10);
  if (!Number.isFinite(n)) return 0;
  if (s.includes('hour') || s.includes('minute') || s.includes('just')) return 0;
  if (s.includes('month')) return n * 30;
  if (s.includes('week')) return n * 7;
  if (s.includes('+')) return n + 1;
  return n;
};
const iso = (d) => { const x = new Date(); x.setDate(x.getDate() - d); return x.toISOString().slice(0, 10); };
// Job type: the sheet column (sample) or Google Jobs' schedule type (live), else words in the job text. Empty = not stated.
const engagementOf = (given, text) => {
  const g = String(given || '').trim();
  if (/contractor|temporary/i.test(g)) return 'Contract';
  if (/contract|perman/i.test(g)) return g;
  const t = String(text || '');
  const p = /\bpermanent\b/i.test(t), c = /\b(contract|temporary)\b/i.test(t);
  return p && c ? 'Contract, Permanent' : p ? 'Permanent' : c ? 'Contract' : '';
};
// Live jobs: Google's own summary (Qualifications, Responsibilities, Benefits) goes first, then the job text.
const highlightsOf = (r) => Array.isArray(r.job_highlights) ? r.job_highlights.map(h => (h.title ? h.title + ': ' : '') + (h.items || []).join('; ')).join('\n') : '';
const out = [];
for (const it of $input.all()) {
  const r = it.json;
  if (r.company_name !== undefined || r.job_id !== undefined) {
    const days = daysFrom(r.detected_extensions && r.detected_extensions.posted_at);
    out.push({ json: { company: r.company_name || '', job_title: r.title || '', location: r.location || '', days_ago: days, job_posted_date: iso(days), description: [highlightsOf(r), String(r.description || '')].filter(Boolean).join('\n').slice(0, 1500), domain: '', contact_name: '', contact_title: '', contact_email: '', engagement: engagementOf(r.detected_extensions && r.detected_extensions.schedule_type, highlightsOf(r) + ' ' + (r.description || '')) } });
  } else {
    const days = Number(r.posted_days_ago) || 0;
    out.push({ json: { company: r.company || '', job_title: r.job_title || '', location: r.location || '', days_ago: days, job_posted_date: iso(days), description: String(r.description || '').slice(0, 1500), domain: r.domain || '', contact_name: r.contact_name || '', contact_title: r.contact_title || '', contact_email: r.contact_email || '', engagement: engagementOf(r.engagement, r.description) } });
  }
}
return out.filter(x => x.json.company && x.json.job_title);

const S = $('Build Settings Object').first().json;
const norm = (s) => String(s || '').toLowerCase().replace(/\b(inc|ltd|llc|corp|co|limited|incorporated|company)\b\.?/g, '').replace(/[^a-z0-9]/g, '');
const leads = $('Read Existing Leads').all().map(i => i.json).filter(r => r.company);
const supp = $('Read Suppression List').all().map(i => i.json);
const sDomains = new Set(supp.map(r => String(r.domain || '').toLowerCase()).filter(Boolean));
const sEmails = new Set(supp.map(r => String(r.email || '').toLowerCase()).filter(Boolean));
const now = new Date();
const known = new Set();
for (const l of leads) {
  const sd = l.sent_date ? new Date(l.sent_date) : null;
  if (!sd || (now - sd) < 90 * 86400000) known.add(norm(l.company));
}
const nameRx = /(staffing|recruit|talent|personnel|workforce|employment|headhunt)/i;
const textRx = /(our client|on behalf of)/i;
// Two posts of one company: one type not stated = not stated overall; else both types.
const joinTypes = (a, b) => (!a || !b) ? '' : [...new Set((a + ',' + b).split(',').map(s => s.trim()).filter(Boolean))].join(', ');
const groups = new Map();
for (const it of $('Drop Old Posts').all()) {
  const v = it.json;
  const k = norm(v.company);
  if (!k || known.has(k)) continue;
  if (v.domain && sDomains.has(String(v.domain).toLowerCase())) continue;
  if (v.contact_email && sEmails.has(String(v.contact_email).toLowerCase())) continue;
  if (S.skip_recruiters && (nameRx.test(v.company) || textRx.test(v.description + ' ' + v.job_title))) continue;
  const g = groups.get(k);
  if (!g) { groups.set(k, Object.assign({}, v, { titles: [v.job_title] })); }
  else {
    if (!g.titles.includes(v.job_title)) g.titles.push(v.job_title);
    g.engagement = joinTypes(g.engagement, v.engagement);
    if (v.days_ago < g.days_ago) { g.days_ago = v.days_ago; g.job_posted_date = v.job_posted_date; }
    g.description = (g.description + ' | ' + v.description).slice(0, 1500);
  }
}
return [...groups.values()].map(g => ({ json: Object.assign({}, g, { job_title: g.titles.join('; ') }) }));

const S = $('Build Settings Object').first().json;
const bench = $('Read Bench').all().map(i => i.json).filter(r => r.profile_id);
// A candidate fits a job when either type is not stated, or they share a type (contract / permanent).
const kinds = s => new Set(String(s || '').toLowerCase().split(/[,;\/&]|\band\b/).map(x => x.trim()).map(x => x.startsWith('perm') ? 'permanent' : (x.startsWith('contract') || x.startsWith('temp')) ? 'contract' : '').filter(Boolean));
const fits = (job, cand) => { const j = kinds(job), c = kinds(cand); return !j.size || !c.size || [...j].some(t => c.has(t)); };
const benchFor = l => { const b = bench.filter(p => fits(l.engagement, p.engagement)); return bench.length ? (b.length ? b.map(p => `${p.profile_id}: ${p.trade}, ${p.certifications}, ${p.region}, available ${p.availability}, ${p.engagement || 'contract or permanent'}`).join('\n') : 'No bench profile fits this job type.') : 'No bench data.'; };
const schema = { type: 'object', additionalProperties: false, required: ['employer_type', 'score', 'reason', 'matched_profiles'],
  properties: { employer_type: { type: 'string', enum: ['direct_employer', 'staffing_agency', 'job_board', 'unknown'] }, score: { type: 'integer', enum: [1, 2, 3, 4, 5] }, reason: { type: 'string' }, matched_profiles: { type: 'array', items: { type: 'string' } } } };
const systemFor = (benchText) => `<role>
You judge whether an employer with an open job is a good prospect for a seller.
</role>
<seller>
What we sell: ${S.what_we_sell}
Who buys: ${S.who_buys}
Job titles that count as a buying signal: ${S.signal_titles.join(', ')}
</seller>
<bench>
${benchText}
</bench>
<rules>
1. employer_type: direct_employer if the company hires for itself. staffing_agency if it recruits for clients (words like "our client", "on behalf of", or it is a recruiter). job_board if it only lists jobs. unknown if the text does not say.
2. score 1 to 5. 5: a direct employer, a role that matches a signal title, and a bench profile in the same region. 4: a good match, no bench profile. 3: unclear fit. 2: weak fit. 1: no fit, the role is unrelated to what the seller sells.
3. A post 14 to 45 days old means the employer is struggling to fill it. Add one point if the score is 3 or 4. Never go above 5.
4. matched_profiles: the profile_id values from the bench that fit the role and the region. Empty array if none. Never invent an id.
5. reason: one plain sentence, from the facts given only.
</rules>
<example>
  <input>{"company":"Dough Brothers Bakery","open_roles":"Pastry Chef","location":"Leeds","days_open":20,"role_text":"Full-time pastry chef for a busy bakery."}</input>
  <output>{"employer_type":"direct_employer","score":4,"reason":"A direct employer with an old open pastry role that matches the seller's catering staff offer.","matched_profiles":["B900"]}</output>
</example>
The example only shows the shape of an answer: never reuse its content.`;
return $input.all().map(it => { const l = it.json; return { json: { lead: l, request: { model: 'z-ai-glm-5-3-flash', temperature: 0, max_tokens: 3000, reasoning_effort: 'low',
  messages: [{ role: 'system', content: systemFor(benchFor(l)) }, { role: 'user', content: JSON.stringify({ company: l.company, open_roles: l.job_title, location: l.location, days_open: l.days_ago, role_text: String(l.description || '').slice(0, 1500), job_type: l.engagement || 'not stated' }) }],
  response_format: { type: 'json_schema', json_schema: { name: 'vacancy_fit', strict: true, schema } } } } }; });

const req = $('Build Score Request').all();
const out = [];
$input.all().forEach((it, i) => {
  const r = it.json;
  const ch = r.choices && r.choices[0];
  if (!ch || ch.finish_reason !== 'stop' || !ch.message || !ch.message.content) {
    throw new Error('Score answer cut off or empty (finish_reason: ' + (ch && ch.finish_reason) + ')');
  }
  let o;
  try { o = JSON.parse(ch.message.content); } catch (e) { throw new Error('Score answer is not valid JSON'); }
  out.push({ json: Object.assign({}, req[i].json.lead, { answer: o }) });
});
return out;

const S = $('Build Settings Object').first().json;
const bad = ['staffing_agency', 'job_board'];
let items = $input.all().map(i => i.json).filter(l => {
  const a = l.answer;
  if (!a) return false;
  if (S.skip_recruiters && bad.includes(a.employer_type)) return false;
  return a.score >= S.min_score;
});
items.sort((a, b) => (b.answer.score - a.answer.score) || (b.days_ago - a.days_ago));
items = items.slice(0, S.daily_cap);
const stamp = Date.now().toString(36);
return items.map((l, i) => ({ json: { lead_id: 'L' + stamp + i, company: l.company, domain: l.domain, job_title: l.job_title, job_posted_date: l.job_posted_date, job_description: l.description,
  score: l.answer.score, score_reason: l.answer.reason, matched_profiles: l.answer.matched_profiles || [], contact_name: l.contact_name, contact_title: l.contact_title, contact_email: l.contact_email, days_ago: l.days_ago, location: l.location, engagement: l.engagement || '' } }));

const lead = $('Take Lead From Call').first().json;
const norm = (s) => String(s || '').toLowerCase().replace(/\b(inc|ltd|llc|corp|co|limited|incorporated|company)\b\.?/g, '').replace(/[^a-z0-9]/g, '');
const boards = /(indeed|linkedin|glassdoor|ziprecruiter|jooble|monster|workopolis|jobbank|facebook|kijiji|craigslist|careerbuilder|simplyhired|talent\.com|adzuna)/i;
const supp = $('When Called By Loop Over Leads').first().json.suppression;
const sDomains = new Set(supp.map(r => String(r.domain || '').toLowerCase()).filter(Boolean));
const cands = ($json.data || []).filter(c => c && c.domain && !boards.test(c.domain));
const exact = cands.filter(c => norm(c.company_name) === norm(lead.company)).sort((a, b) => (b.email_count || 0) - (a.email_count || 0));
const pick = exact[0];
const dom = pick && !sDomains.has(String(pick.domain).toLowerCase()) ? pick.domain : '';
return { json: Object.assign({}, lead, { domain: dom }) };

const lead = $('Pick Exact Website Match').first().json;
const titleRx = /(owner|president|founder|ceo|operations|human resources|\bhr\b|hiring|general manager|recruit|office manager|talent|people|superintendent|plant manager|director)/i;
const emails = $input.all().map(i => i.json).filter(e => e.value || e.email);
const ok = emails.map(e => ({ email: e.value || e.email, first: e.first_name || '', last: e.last_name || '', title: e.position || '', status: e.verification && e.verification.status, conf: e.confidence || 0 }))
  .filter(e => e.email && e.status === 'valid' && titleRx.test(e.title));
ok.sort((a, b) => b.conf - a.conf);
const best = ok[0];
return [{ json: Object.assign({}, lead, best ? { contact_name: (best.first + ' ' + best.last).trim(), contact_title: best.title, contact_email: best.email } : { contact_name: '', contact_title: '', contact_email: '' }) }];

const S = $('When Called By Loop Over Leads').first().json.settings;
const bench = $('When Called By Loop Over Leads').first().json.bench.filter(r => r.profile_id);
const lead = $json;
const matched = bench.filter(b => (lead.matched_profiles || []).includes(b.profile_id));
const first = String(lead.contact_name || '').split(' ')[0] || '';
const schema = { type: 'object', additionalProperties: false, required: ['subject', 'body'], properties: { subject: { type: 'string' }, body: { type: 'string' } } };
const system = `<role>
You write one short cold email from a seller to a hiring contact at a company that has an open job.
</role>
<seller>
Sender name: ${S.sender_name}
Company: ${S.sender_company}
What we sell: ${S.what_we_sell}
Tone: ${S.tone}
</seller>
<rules>
1. 90 to 120 words. Plain text. No markdown. No emojis.
2. Name the specific open role and the company in the first two lines.
3. Use only the facts given. Never invent names, numbers, results or claims.
4. If matched candidates are given, say how many match and when they can start, using only the given data. Never give personal details. If none are given, offer to send profiles and do not claim that any exist.
5. End with one question that is easy to answer.
6. Sign with the sender name only. A footer is added later: do not write an address or an opt-out line.
7. Greet with the contact first name. If it is empty, write "Hello".
</rules>
<example>
  <input>{"company":"Dough Brothers Bakery","open_roles":"Pastry Chef","location":"Leeds","days_open":20,"contact_first_name":"Sam","matched_candidates":[{"trade":"Pastry chef","region":"Leeds","available":"1 week"}]}</input>
  <output>{"subject":"Your pastry chef opening","body":"Hi Sam,\n\nI saw Dough Brothers Bakery has had a pastry chef role open for about 20 days. We have one pastry chef in Leeds who can start in a week.\n\nWould you like me to send a short profile?\n\nAlex"}</output>
</example>
The example only shows the shape of an answer: never reuse its content.`;
const user = JSON.stringify({ company: lead.company, open_roles: lead.job_title, location: lead.location, days_open: lead.days_ago, role_text: String(lead.job_description || '').slice(0, 1500), job_type: lead.engagement || 'not stated', contact_first_name: first, contact_title: lead.contact_title,
  matched_candidates: matched.map(m => ({ trade: m.trade, certifications: m.certifications, region: m.region, available: m.availability, engagement: m.engagement || 'contract or permanent' })) });
return { json: { lead, request: { model: 'z-ai-glm-5-3-flash', temperature: 0.3, max_tokens: 3000, reasoning_effort: 'low',
  messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  response_format: { type: 'json_schema', json_schema: { name: 'email_draft', strict: true, schema } } } } };

const req = $('Build Draft Request').all();
const out = [];
$input.all().forEach((it, i) => {
  const r = it.json;
  const ch = r.choices && r.choices[0];
  if (!ch || ch.finish_reason !== 'stop' || !ch.message || !ch.message.content) {
    throw new Error('Email draft answer cut off or empty (finish_reason: ' + (ch && ch.finish_reason) + ')');
  }
  let o;
  try { o = JSON.parse(ch.message.content); } catch (e) { throw new Error('Email draft answer is not valid JSON'); }
  out.push({ json: Object.assign({}, req[i].json.lead, { answer: o }) });
});
return out;

const S = $('When Called By Loop Over Leads').first().json.settings;
const l = $json;
const a = l.answer;
if (!S.sender_name || /YOUR NAME/i.test(S.sender_name) || !S.postal_address || /REPLACE/i.test(S.postal_address)) {
  throw new Error('Sender details missing: fill sender_name and postal_address in the Offer tab');
}
if (/REPLACE_WITH/i.test(l.contact_email)) {
  throw new Error('Sample contact emails still hold REPLACE_WITH_YOUR_TEST_EMAIL: replace it with your own address');
}
const supp = $('When Called By Loop Over Leads').first().json.suppression;
const email = String(l.contact_email).toLowerCase();
const dom = String(l.domain || '').toLowerCase();
const blocked = supp.some(r => (r.email && String(r.email).toLowerCase() === email) || (r.domain && dom && String(r.domain).toLowerCase() === dom));
const footer = '\n\n--\n' + S.sender_name + '\n' + S.sender_company + '\n' + S.postal_address + '\nReply STOP and I will not write again.';
const out = Object.assign({}, l);
delete out.answer;
return { json: Object.assign(out, { email_subject: a.subject, email_body: String(a.body).trim() + footer, allowed: !blocked }) };

options.responseFormCustomCss:
#submitted-form { text-align: center; }
#submitted-header { font-size: 0; }
#submitted-header::before { content: '✅'; display: block; font-size: 72px; line-height: 1; margin-bottom: 20px; }
#submitted-header::after { content: 'Approved'; display: block; font-size: 34px; }
#submitted-content { font-size: 0; }
#submitted-content::after { content: 'Your edited email is saved as ready. It goes out with the next daily send.'; font-size: 19px; color: #5b6475; }
#submitted-form .n8n-link { display: none; }
